INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 7, "キャル", 7001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 7, "コッコロ", 7002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 7, "ペコリーヌ", 7003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 10, "ペコリーヌ", 10001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 10, "キャル", 10002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 10, "コッコロ", 10003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 2, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 10, "シェフィ", 10004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 0.0, 1, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 12, "ペコリーヌ", 12001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 13, "キャル", 13001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 13, "コッコロ", 13002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 2, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 13, "シェフィ", 13003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 13, "ペコリーヌ", 13004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 14, "コッコロ", 14001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 2, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 14, "シェフィ", 14002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 14, "ペコリーヌ", 14003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 14, "キャル", 14004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-470.0, 0.0, 1, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 15, "コッコロ", 15001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 2, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 16, "シェフィ", 16001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 16, "ペコリーヌ", 16002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 16, "キャル", 16003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 16, "コッコロ", 16004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 17, "コッコロ", 17002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 25, "キャル", 17004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 25, "コッコロ", 17005, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 2, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 25, "シェフィ", 17006, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 25, "ペコリーヌ", 17007, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 18, "カリン", 18001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 2, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 18, "カリン", 18002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-470.0, 0.0, 1, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 3, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 19, "カリン", 19001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-470.0, 0.0, 1, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 4, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 19, "カリン", 19002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-470.0, 0.0, 1, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 5, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 20, "カリン", 20001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-470.0, 0.0, 1, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 6, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 20, "カリン", 20002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 21, "キャル", 21001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 21, "コッコロ", 21002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 2, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 21, "シェフィ", 21003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 21, "ペコリーヌ", 21004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-430.0, 0.0, 1, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 22, "カリン", 22001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-430.0, 0.0, 1, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 2, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 22, "カリン", 22002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-430.0, 0.0, 1, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 3, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 23, "カリン", 23001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-430.0, 0.0, 1, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 4, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 23, "カリン", 23002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 4.08, 1, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 1, 8.0, 10011, 0, "2030/12/17 14:59:59", 109001, 2, 24, "エリコ（バレンタイン）", 24001, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 5.0, 1, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 2, 8.0, 10011, 0, "2030/12/17 14:59:59", 109001, 2, 24, "エリコ（バレンタイン）", 24002, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 10.11, 1, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 3, 8.0, 10011, 0, "2030/12/17 14:59:59", 109001, 2, 24, "エリコ（バレンタイン）", 24003, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 4.0, 1, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 4, 8.0, 10011, 0, "2030/12/17 14:59:59", 109001, 2, 24, "エリコ（バレンタイン）", 24004, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 6.0, 1, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 5, 8.0, 10011, 0, "2030/12/17 14:59:59", 109001, 2, 24, "エリコ（バレンタイン）", 24005, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 6, 0.0, 10011, 0, "2030/12/17 14:59:59", 109002, 1, 24, "エリコ（バレンタイン）", 24006, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 7, 0.0, 10011, 0, "2030/12/17 14:59:59", 109002, 1, 24, "エリコ（バレンタイン）", 24007, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 8, 0.0, 10011, 0, "2030/12/17 14:59:59", 109002, 1, 24, "エリコ（バレンタイン）", 24008, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 9, 0.0, 10011, 0, "2030/12/17 14:59:59", 109002, 1, 24, "エリコ（バレンタイン）", 24009, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 10, 0.0, 10011, 0, "2030/12/17 14:59:59", 109002, 1, 24, "エリコ（バレンタイン）", 24010, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 2.12, 1, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 1, 8.0, 10011, 0, "2030/12/17 14:59:59", 109101, 2, 24, "シズル（バレンタイン）", 24011, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 4.19, 5, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 2, 8.0, 10011, 0, "2030/12/17 14:59:59", 109101, 2, 24, "シズル（バレンタイン）", 24012, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 2.3, 2, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 3, 8.0, 10011, 0, "2030/12/17 14:59:59", 109101, 4, 24, "シズル（バレンタイン）", 24013, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 4, 0.0, 10011, 0, "2030/12/17 14:59:59", 109102, 1, 24, "シズル（バレンタイン）", 24014, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 5.23, 5, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 5, 8.0, 10011, 0, "2030/12/17 14:59:59", 109101, 2, 24, "シズル（バレンタイン）", 24015, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 6, 0.0, 10011, 0, "2030/12/17 14:59:59", 109102, 1, 24, "シズル（バレンタイン）", 24016, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-385.0, 5.01, 1, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 7, 8.0, 10011, 0, "2030/12/17 14:59:59", 109101, 2, 24, "シズル（バレンタイン）", 24017, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 8, 0.0, 10011, 0, "2030/12/17 14:59:59", 109102, 1, 24, "シズル（バレンタイン）", 24018, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 9, 0.0, 10011, 0, "2030/12/17 14:59:59", 109102, 1, 24, "シズル（バレンタイン）", 24019, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0.0, 0.0, 1, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 10, 0.0, 10011, 0, "2030/12/17 14:59:59", 109102, 1, 24, "シズル（バレンタイン）", 24020, "2019/01/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 2, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 26, "シェフィ", 26001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 26, "ペコリーヌ", 26002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 26, "キャル", 26003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 26, "コッコロ", 26004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 2, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 27, "シェフィ", 27001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 27, "ペコリーヌ", 27002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 27, "キャル", 27003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 27, "コッコロ", 27004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 28, "カリン", 28001, "2019/09/24 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", 2, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 28, "カリン", 28002, "2019/09/24 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", 3, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 29, "カリン", 29001, "2019/09/24 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 4, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 29, "カリン", 29002, "2019/09/24 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 5, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 30, "カリン", 30001, "2019/09/24 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", 6, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 30, "カリン", 30002, "2019/09/24 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", 7, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 31, "カリン", 31001, "2019/10/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", 8, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 31, "カリン", 31002, "2019/10/31 12:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", 1, 0.0, 0, 0, "2020/01/04 4:59:59", 190801, 1, 32, "カリン", 32001, "2019/12/20 5:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 2, 0.0, 0, 0, "2020/01/04 4:59:59", 190801, 1, 32, "カリン", 32002, "2019/12/20 5:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", 3, 0.0, 0, 0, "2020/01/04 4:59:59", 190801, 1, 33, "カリン", 33001, "2019/12/20 5:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 4, 0.0, 0, 0, "2020/01/04 4:59:59", 190801, 1, 33, "カリン", 33002, "2019/12/20 5:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", 5, 0.0, 0, 0, "2020/01/10 11:59:59", 190801, 1, 34, "カリン", 34001, "2020/01/04 5:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-409.0, 0.0, 1, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", 6, 0.0, 0, 0, "2020/01/10 11:59:59", 190801, 1, 34, "カリン", 34002, "2020/01/04 5:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-458.0, 5.3, 1, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 2, 38, "ペコリーヌ", 38001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-458.0, 6.5, 1, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", 2, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 2, 38, "ペコリーヌ", 38002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (9999.0, 0.0, 3, "", 0, 9999.0, 0, 0, "2020/04/08 23:59:59", 105801, 3, 39, "ペコリーヌ", 39005, "2020/04/01");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-430.0, 0.0, 1, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", 2, 0.0, 0, 0, "2030/12/17 14:59:59", 190801, 1, 40, "カリン", 40001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 41, "シェフィ", 41001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 41, "ペコリーヌ", 41002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 41, "キャル", 41003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 41, "コッコロ", 41004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 0.0, 1, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 42, "コッコロ", 42001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 0.0, 1, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", 1, 0.0, 0, 2104010, "2030/12/17 14:59:59", 106401, 1, 42, "シェフィ", 42002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 0.0, 1, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 42, "ペコリーヌ", 42003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 0.0, 1, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 42, "キャル", 42004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105801, 1, 43, "ペコリーヌ", 43001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 105901, 1, 43, "コッコロ", 43002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-363.0, 0.0, 1, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 106001, 1, 43, "キャル", 43003, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 0.0, 1, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 123001, 1, 44, "アメス", 43004, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 0.0, 1, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 2, 0.0, 0, 0, "2030/12/17 14:59:59", 123001, 1, 44, "アメス", 43005, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 5.79, 1, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 3, 0.0, 0, 0, "2030/12/17 14:59:59", 123001, 2, 45, "アメス", 43006, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-371.5, 0.0, 1, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 123001, 1, 46, "アメス", 46001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 0.0, 2, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 104901, 2, 47, "シズル", 47001, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-416.5, 9.32, 1, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 1, 0.0, 0, 0, "2030/12/17 14:59:59", 101101, 2, 47, "リノ", 47002, "2015/12/17 15:00:00");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (-470.0, 0.0, 2, "", 0, 0.0, 0, 0, "2030/12/17 14:59:59", 104901, 2, 48, "シズル", 48001, "2015/12/17 15:00:00");
